const menu=document.querySelector('.menu');const nav=document.querySelector('nav');menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open)});
const form=document.querySelector('#demo-form');if(form){const subject=new URLSearchParams(location.search).get('sujet');if([...form.elements.sujet.options].some(o=>o.value===subject))form.elements.sujet.value=subject;form.addEventListener('submit',e=>{e.preventDefault();const d=new FormData(form);const result=document.querySelector('#result');result.hidden=false;result.textContent='Votre simulation est prête. Rien n’a été envoyé.\n\nNom : '+d.get('nom')+'\nBesoin : '+d.get('sujet')+'\nÉchéance : '+d.get('delai')+'\nContexte : '+(d.get('contexte')||'Non précisé')+'\nProjet : '+d.get('message')})}
const filterButtons=[...document.querySelectorAll('[data-filter]')];filterButtons.forEach(button=>button.addEventListener('click',()=>{filterButtons.forEach(b=>b.setAttribute('aria-pressed',String(b===button)));let count=0;document.querySelectorAll('.rich-card').forEach(card=>{const show=button.dataset.filter==='Tout'||card.dataset.category===button.dataset.filter;card.hidden=!show;if(show)count++});document.querySelector('#filter-count').textContent=count+' résultat'+(count>1?'s':'')}));
const diagnostic=document.querySelector('#diagnostic');diagnostic?.addEventListener('change',()=>{const choices=[['Rendre les rôles explicites','Un organigramme fonctionnel, une matrice de responsabilités et trois règles de décision partagées.'],['Tester une hypothèse commerciale','Une proposition de valeur, un guide d’entretien et un protocole de test avant lancement.'],['Choisir des indicateurs utiles','Un tableau de bord limité à quelques indicateurs avec une fréquence de revue définie.']];const i=Number(diagnostic.value);const result=document.querySelector('#diagnostic-result');result.querySelector('h3').textContent=choices[i][0];result.querySelector('p').textContent=choices[i][1];result.querySelector('a').href='/demos/cabinet/detail-'+(i+1)+'/'});
if(form){const requested=new URLSearchParams(location.search).get('sujet');if(requested&&requested.length<120&&![...form.elements.sujet.options].some(o=>o.value===requested)){const option=document.createElement('option');option.textContent=requested;option.value=requested;form.elements.sujet.add(option);form.elements.sujet.value=requested}}
